/**
 * \author Mr.Nobody
 * \file Dac_Dma.c
 * \ingroup Dac
 * \brief Dac module DMA data transfer handler
 *
 * DAC_TRANSFER_MODE_DMA - output values are moved from the user buffer to the channel data
 * holding register by a GPDMA channel (memory to peripheral, 16-bit, one block of BufferSize
 * items) on every DAC DMA request (generated by the channel hardware trigger).
 * - Half transfer / transfer complete / DMA errors are reported from GPDMA interrupt.
 * - DMA underrun (DMAUDRx) is reported from DAC interrupt (see Dac_Isr.c).
 * - DAC_BUFFER_MODE_CIRCULAR: the transfer list node is linked to itself
 *   (GPDMA_XFER_LIST_EXEC_CYCLIC_ALL), the block is reloaded by GPDMA HW without SW
 *   intervention. DAC_BUFFER_MODE_ONE_SHOT: the transfer list is terminated after the block.
 * - The transfer list node is regenerated on every start (buffer, buffer mode and data
 *   holding register of the actual data format).
 *
 * Transfer state and user callbacks are implemented in Dac.c (Dac_Set_Xfer* services).
 *
 */
/* ============================== INCLUDES ================================== */
#include "Dac_Dma.h"                        /* Self include                   */
#include "Dac_Isr.h"                        /* DAC interrupt handler          */
#include "Dac.h"                            /* Module private interface       */
#include "Gpdma_Port.h"                     /* GPDMA Mcal layer include       */
/* ============================== TYPEDEFS ================================== */

/** DAC channel DMA request connection to GPDMA */
typedef struct
{
    gpdma_PeriphReqId_t   Request;     /**< GPDMA request identification                  */
    gpdma_IsrCallback    *XferCpltIsr; /**< Transfer complete handler of the channel      */
    gpdma_IsrCallback    *HalfXferIsr; /**< Half transfer handler of the channel          */
    gpdma_IsrErrCallback *ErrorIsr;    /**< Transfer error handler of the channel         */
}   dac_DmaReqConfig_t;


/** GPDMA channel ownership of a DAC channel (GPDMA channel can not be de-initialized separately) */
typedef struct
{
    dac_FunctionState_t Initialized; /**< GPDMA channel was initialized for the DAC channel */
    dac_DmaPeriphId_t   PeriphId;    /**< Initialized GPDMA peripheral                      */
    dac_DmaChannelId_t  ChannelId;   /**< Initialized GPDMA channel                         */
}   dac_DmaChannelState_t;

/* ======================== FORWARD DECLARATIONS ============================ */

static dac_RequestState_t Dac_Dma_Get_XferConfig( dac_PeriphId_t periphId, dac_ChannelId_t channelId, gpdma_TransferConfig_t * const xferConfig );
static dac_RequestState_t Dac_Dma_Set_Transfer  ( dac_PeriphId_t periphId, dac_ChannelId_t channelId );
static dac_RequestState_t Dac_Dma_Set_Request   ( dac_PeriphId_t periphId, dac_ChannelId_t channelId, dac_FunctionState_t reqState );
static dac_RequestState_t Dac_Dma_XferCplt      ( dac_PeriphId_t periphId, dac_ChannelId_t channelId );
static dac_RequestState_t Dac_Dma_XferError     ( dac_PeriphId_t periphId, dac_ChannelId_t channelId, gpdma_ErrorMaskId_t errorMask );

static void               Dac_Dma_Ch1XferCplt   ( void );
static void               Dac_Dma_Ch1HalfXfer   ( void );
static void               Dac_Dma_Ch1Error      ( gpdma_ErrorMaskId_t errorMask );
static void               Dac_Dma_Ch2XferCplt   ( void );
static void               Dac_Dma_Ch2HalfXfer   ( void );
static void               Dac_Dma_Ch2Error      ( gpdma_ErrorMaskId_t errorMask );

/* ========================== SYMBOLIC CONSTANTS ============================ */

/** Count of data items transferred per DMA request (single transfer) */
#define DAC_DMA_BURST_LEN            ( 1u )

/** Count of transfers in GPDMA transfer list (one block of BufferSize items) */
#define DAC_DMA_TRANSFERS_CNT        ( 1u )

/** Maximum buffer size in dac_Data_t items - GPDMA block size is limited to 16 bits (bytes) */
#define DAC_DMA_BUFFER_SIZE_MAX      ( (uint32_t)UINT16_MAX / (uint32_t)sizeof( dac_Data_t ) )

/** GPDMA errors reported to the user */
#define DAC_DMA_ERROR_MASK           ( GPDMA_ERROR_TRANSFER      | \
                                       GPDMA_ERROR_CONFIG_UPDATE | \
                                       GPDMA_ERROR_CONFIG_ERROR  | \
                                       GPDMA_ERROR_TRIG_OVERRUN    )

/** GPDMA error bit of DAC errors which are not reported by GPDMA (DMA underrun) */
#define DAC_DMA_ERROR_NONE           ( 0u )

/* =============================== MACROS =================================== */

/* ========================== EXPORTED VARIABLES ============================ */

/* =========================== LOCAL VARIABLES ============================== */

/** dac_PeriphId_t x dac_ChannelId_t -> GPDMA request and handlers */
static const dac_DmaReqConfig_t dac_DmaReqConfig[ DAC_PERIPH_CNT ][ DAC_CHANNEL_CNT ] =
{
    [DAC_PERIPH_1] =
    {
        [DAC_CHANNEL_1] = { .Request = GPDMA_REQ_DAC1_CH1, .XferCpltIsr = Dac_Dma_Ch1XferCplt, .HalfXferIsr = Dac_Dma_Ch1HalfXfer, .ErrorIsr = Dac_Dma_Ch1Error },
        [DAC_CHANNEL_2] = { .Request = GPDMA_REQ_DAC1_CH2, .XferCpltIsr = Dac_Dma_Ch2XferCplt, .HalfXferIsr = Dac_Dma_Ch2HalfXfer, .ErrorIsr = Dac_Dma_Ch2Error },
    },
};


/** dac_ErrorId_t -> GPDMA error bit reporting the error */
static const uint32_t dac_DmaErrorMaskLut[ DAC_ERROR_CNT ] =
{
    [DAC_ERROR_DMA_UNDERRUN]        = DAC_DMA_ERROR_NONE,
    [DAC_ERROR_DMA_TRANSFER]        = GPDMA_ERROR_TRANSFER,
    [DAC_ERROR_DMA_CONFIG]          = GPDMA_ERROR_CONFIG_ERROR,
    [DAC_ERROR_DMA_CONFIG_UPDATE]   = GPDMA_ERROR_CONFIG_UPDATE,
    [DAC_ERROR_DMA_TRIGGER_OVERRUN] = GPDMA_ERROR_TRIG_OVERRUN,
};


/** dac_BufferMode_t -> GPDMA transfer list execution mode */
static const gpdma_XferListExecMode_t dac_DmaListModeLut[ DAC_BUFFER_MODE_CNT ] =
{
    [DAC_BUFFER_MODE_ONE_SHOT] = GPDMA_XFER_LIST_EXEC_ONCE,
    [DAC_BUFFER_MODE_CIRCULAR] = GPDMA_XFER_LIST_EXEC_CYCLIC_ALL,
};


/** dac_DmaChannelId_t -> GPDMA channel type (channels 6 and 7 support 2D addressing,
 *  see gpdma_ChannelId_t in Gpdma_Types.h) - layout of the transfer list node */
static const gpdma_ChannelType_t dac_DmaChannelTypeLut[ DAC_DMA_CHANNEL_CNT ] =
{
    [DAC_DMA_CHANNEL_0] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_1] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_2] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_3] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_4] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_5] = GPDMA_CHANNEL_LINEAR,
    [DAC_DMA_CHANNEL_6] = GPDMA_CHANNEL_LINEAR_2D,
    [DAC_DMA_CHANNEL_7] = GPDMA_CHANNEL_LINEAR_2D,
};


/** GPDMA transfer lists (must be static, used by GPDMA HW) */
static gpdma_XferList_t dac_DmaXferList[ DAC_PERIPH_CNT ][ DAC_CHANNEL_CNT ];


/** GPDMA channel ownership per DAC channel */
static dac_DmaChannelState_t dac_DmaChannelState[ DAC_PERIPH_CNT ][ DAC_CHANNEL_CNT ];

/* ========================= EXPORTED FUNCTIONS ============================= */

/**
 * \brief Checks DMA related part of the data transfer configuration
 *
 * \param periphId   [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId  [in]: DAC channel identification, value from \ref dac_ChannelId_t
 * \param dataConfig [in]: Pointer to data transfer configuration. Must not be NULL.
 *
 * \return Returns \ref DAC_REQUEST_OK if DMA identifications are valid, the GPDMA channel is not
 *         owned by another DAC channel, DataBuffer is set and BufferSize is within
 *         1 - DAC_DMA_BUFFER_SIZE_MAX. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
dac_RequestState_t Dac_Dma_Check_Config( dac_PeriphId_t periphId, dac_ChannelId_t channelId, const dac_DataConfig_t * const dataConfig )
{
    dac_RequestState_t retState = DAC_REQUEST_ERROR;

    if( ( DAC_PERIPH_CNT                > periphId                           ) &&
        ( DAC_CHANNEL_CNT               > channelId                          ) &&
        ( DAC_NULL_PTR                 != dataConfig                         ) &&
        ( DAC_NULL_PTR                 != dataConfig->DataBuffer             ) &&
        ( 0u                            < dataConfig->BufferSize             ) &&
        ( DAC_DMA_BUFFER_SIZE_MAX      >= (uint32_t)dataConfig->BufferSize   ) &&
        ( DAC_BUFFER_MODE_CNT           > dataConfig->BufferMode             ) &&
        ( DAC_DMA_PERIPH_CNT            > dataConfig->DmaPeriphId            ) &&
        ( DAC_DMA_CHANNEL_CNT           > dataConfig->DmaChannelId           ) &&
        ( (uint32_t)GPDMA_PRIORITY_CNT  > (uint32_t)dataConfig->DmaPriority  )    )
    {
        retState = DAC_REQUEST_OK;

        /* GPDMA channel owned by another DAC channel can not be shared */
        for( dac_PeriphId_t ownerPeriph = DAC_PERIPH_1; DAC_PERIPH_CNT > ownerPeriph; ownerPeriph ++ )
        {
            for( dac_ChannelId_t ownerChannel = DAC_CHANNEL_1; DAC_CHANNEL_CNT > ownerChannel; ownerChannel ++ )
            {
                const dac_DmaChannelState_t * const owner = &dac_DmaChannelState[ ownerPeriph ][ ownerChannel ];

                if( ( ( periphId != ownerPeriph ) || ( channelId != ownerChannel ) ) &&
                    ( DAC_FUNCTION_ACTIVE      == owner->Initialized              ) &&
                    ( dataConfig->DmaPeriphId  == owner->PeriphId                 ) &&
                    ( dataConfig->DmaChannelId == owner->ChannelId                )    )
                {
                    retState = DAC_REQUEST_ERROR;
                }
                else
                {
                    /* GPDMA channel is not owned by other DAC channel */
                }
            }
        }
    }
    else
    {
        /* DMA configuration is invalid */
        retState = DAC_REQUEST_ERROR;
    }

    return ( retState );
}


/**
 * \brief Initializes DMA data transfer: GPDMA channel, DAC interrupt (DMA underrun), DAC DMA
 *        requests are kept disabled until the start
 *
 * \note  A GPDMA channel already initialized for the DAC channel by a previous initialization is
 *        reused (GPDMA module does not support de-initialization of a single channel) - only
 *        its priority and half transfer interrupt are updated.
 *
 * \pre   Transfer context of the channel contains the data transfer configuration.
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
dac_RequestState_t Dac_Dma_Init( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t  retState = DAC_REQUEST_ERROR;
    dac_XferContext_t * xferCtx  = DAC_NULL_PTR;

    retState = Dac_Get_XferContext( periphId, channelId, &xferCtx );

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Dma_Check_Config( periphId, channelId, &xferCtx->Config );
    }

    /* --- DAC DMA requests are disabled until the transfer is started --- */
    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Dma_Set_Request( periphId, channelId, DAC_FUNCTION_INACTIVE );
    }

    /* --- GPDMA channel --- */
    if( DAC_REQUEST_OK == retState )
    {
        dac_DmaChannelState_t * const    chState   = &dac_DmaChannelState[ periphId ][ channelId ];
        const dac_DmaReqConfig_t * const reqConfig = &dac_DmaReqConfig[ periphId ][ channelId ];
        const gpdma_PeriphId_t           dmaPeriph = (gpdma_PeriphId_t)xferCtx->Config.DmaPeriphId;
        const gpdma_ChannelId_t          dmaChan   = (gpdma_ChannelId_t)xferCtx->Config.DmaChannelId;
        gpdma_RequestState_t             dmaState  = GPDMA_REQUEST_ERROR;

        if( ( DAC_FUNCTION_ACTIVE          == chState->Initialized ) &&
            ( xferCtx->Config.DmaPeriphId  == chState->PeriphId    ) &&
            ( xferCtx->Config.DmaChannelId == chState->ChannelId   )    )
        {
            /* Channel is already configured for this DAC channel - priority and half transfer are updated */
            dmaState = Gpdma_Set_Priority( dmaPeriph, dmaChan, (gpdma_Priority_t)xferCtx->Config.DmaPriority );

            if( ( GPDMA_REQUEST_OK == dmaState ) && ( DAC_NULL_PTR != xferCtx->Config.HalfTransferCallback ) )
            {
                dmaState = Gpdma_Set_HalfTransferIsrHandler( dmaPeriph, dmaChan, reqConfig->HalfXferIsr );

                if( GPDMA_REQUEST_OK == dmaState )
                {
                    dmaState = Gpdma_Set_HalfTransferIrqActive( dmaPeriph, dmaChan );
                }
                else
                {
                    /* Handler registration failed, interrupt is not enabled */
                }
            }
            else if( GPDMA_REQUEST_OK == dmaState )
            {
                dmaState = Gpdma_Set_HalfTransferIrqInactive( dmaPeriph, dmaChan );
            }
            else
            {
                /* Priority configuration failed */
            }
        }
        else
        {
            gpdma_ConfigStruct_t   dmaConfig  = { 0u };
            gpdma_TransferConfig_t xferConfig = { 0u };

            /* Transfer configuration was checked above, the result is always OK here */
            (void)Dac_Dma_Get_XferConfig( periphId, channelId, &xferConfig );

            dmaState = Gpdma_Get_DefaultConfig( &dmaConfig );

            dmaConfig.PeriphId            = dmaPeriph;
            dmaConfig.ChannelId           = dmaChan;
            dmaConfig.ChannelPrio         = (gpdma_Priority_t)xferCtx->Config.DmaPriority;
            dmaConfig.TransferExecMode    = GPDMA_XFER_EXEC_CONTINUOUS;
            dmaConfig.TransferConfig      = &xferConfig;
            dmaConfig.TransfersCount      = DAC_DMA_TRANSFERS_CNT;
            dmaConfig.XferListAccessMode  = GPDMA_TRANSFER_LIST_ACCESS_SINGLE;
            dmaConfig.XferList            = &dac_DmaXferList[ periphId ][ channelId ];
            dmaConfig.TransferLockState   = GPDMA_TRANSFER_LIST_LOCKED;

            /* Transfer complete is always needed (one shot stop / circular buffer event) */
            dmaConfig.TransferCompleteIsr = reqConfig->XferCpltIsr;
            dmaConfig.ErrorIsr            = reqConfig->ErrorIsr;
            dmaConfig.ErrorMask           = DAC_DMA_ERROR_MASK;

            if( DAC_NULL_PTR != xferCtx->Config.HalfTransferCallback )
            {
                dmaConfig.HalfTransferIsr = reqConfig->HalfXferIsr;
            }
            else
            {
                dmaConfig.HalfTransferIsr = GPDMA_NULL_PTR;
            }

            if( GPDMA_REQUEST_OK == dmaState )
            {
                dmaState = Gpdma_Init( &dmaConfig );
            }
            else
            {
                /* Default configuration is not available */
            }

            if( GPDMA_REQUEST_OK == dmaState )
            {
                chState->Initialized = DAC_FUNCTION_ACTIVE;
                chState->PeriphId    = xferCtx->Config.DmaPeriphId;
                chState->ChannelId   = xferCtx->Config.DmaChannelId;
            }
            else
            {
                /* GPDMA channel initialization failed */
            }
        }

        /* GPDMA module does not enable the channel interrupt in NVIC by itself */
        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_InterruptActive( dmaPeriph, dmaChan );
        }
        else
        {
            /* GPDMA channel configuration failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            retState = DAC_REQUEST_OK;
        }
        else
        {
            retState = DAC_REQUEST_ERROR;
        }
    }

    /* --- DAC interrupt for DMA underrun --- */
    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Isr_Init( periphId, xferCtx->Config.IrqPriority );
    }

    return ( retState );
}


/**
 * \brief Deinitializes DMA data transfer: transfer stopped, GPDMA channel interrupt disabled
 *
 * \note  GPDMA channel configuration is kept (see Dac_Dma_Init()), the DAC interrupt in NVIC is
 *        disabled by Dac_Deinit() (shared by both channels).
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
dac_RequestState_t Dac_Dma_Deinit( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t retState = DAC_REQUEST_ERROR;

    retState = Dac_Dma_Stop( periphId, channelId );

    if( ( DAC_REQUEST_OK == retState ) && ( DAC_FUNCTION_ACTIVE == dac_DmaChannelState[ periphId ][ channelId ].Initialized ) )
    {
        const gpdma_PeriphId_t     dmaPeriph = (gpdma_PeriphId_t)dac_DmaChannelState[ periphId ][ channelId ].PeriphId;
        const gpdma_ChannelId_t    dmaChan   = (gpdma_ChannelId_t)dac_DmaChannelState[ periphId ][ channelId ].ChannelId;
        const gpdma_RequestState_t dmaState  = Gpdma_Set_InterruptInactive( dmaPeriph, dmaChan );

        if( GPDMA_REQUEST_OK == dmaState )
        {
            retState = DAC_REQUEST_OK;
        }
        else
        {
            retState = DAC_REQUEST_ERROR;
        }
    }
    else
    {
        /* Transfer could not be stopped or no GPDMA channel was initialized for the DAC channel */
    }

    return ( retState );
}


/**
 * \brief Starts DMA data transfer - GPDMA channel is armed for the whole buffer, DAC DMA requests
 *        and DMA underrun interrupt are enabled
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
dac_RequestState_t Dac_Dma_Start( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t retState = DAC_REQUEST_ERROR;

    retState = Dac_Dma_Set_Transfer( periphId, channelId );

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Isr_Set_UnderrunIrqActive( periphId, channelId );
    }

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Dma_Set_Request( periphId, channelId, DAC_FUNCTION_ACTIVE );
    }

    return ( retState );
}


/**
 * \brief Stops DMA data transfer - DAC DMA requests, DMA underrun interrupt and GPDMA channel
 *        are disabled
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
dac_RequestState_t Dac_Dma_Stop( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t retState = DAC_REQUEST_ERROR;

    retState = Dac_Dma_Set_Request( periphId, channelId, DAC_FUNCTION_INACTIVE );

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Isr_Set_UnderrunIrqInactive( periphId, channelId );
    }

    if( ( DAC_REQUEST_OK == retState ) && ( DAC_FUNCTION_ACTIVE == dac_DmaChannelState[ periphId ][ channelId ].Initialized ) )
    {
        const gpdma_RequestState_t dmaState = Gpdma_Set_ChannelInactive( (gpdma_PeriphId_t)dac_DmaChannelState[ periphId ][ channelId ].PeriphId,
                                                                         (gpdma_ChannelId_t)dac_DmaChannelState[ periphId ][ channelId ].ChannelId );

        if( GPDMA_REQUEST_OK == dmaState )
        {
            retState = DAC_REQUEST_OK;
        }
        else
        {
            retState = DAC_REQUEST_ERROR;
        }
    }
    else
    {
        /* Stop failed or no GPDMA channel was initialized for the DAC channel */
    }

    return ( retState );
}

/* =========================== LOCAL FUNCTIONS ============================== */

/**
 * \brief Fills GPDMA transfer configuration of a DAC channel (memory to peripheral, 16-bit, one
 *        block of BufferSize items, destination = data holding register of the actual format,
 *        list execution mode by buffer mode)
 *
 * \param periphId    [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId   [in]: DAC channel identification, value from \ref dac_ChannelId_t
 * \param xferConfig [out]: Pointer to transfer configuration to be filled. Must not be NULL.
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
static dac_RequestState_t Dac_Dma_Get_XferConfig( dac_PeriphId_t periphId, dac_ChannelId_t channelId, gpdma_TransferConfig_t * const xferConfig )
{
    dac_RequestState_t  retState = DAC_REQUEST_ERROR;
    dac_XferContext_t * xferCtx  = DAC_NULL_PTR;
    uint32_t            regAddr  = 0u;

    retState = Dac_Get_XferContext( periphId, channelId, &xferCtx );

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Get_DataRegAddr( periphId, channelId, &regAddr );
    }

    if( ( DAC_REQUEST_OK      == retState                   ) &&
        ( DAC_NULL_PTR        != xferConfig                 ) &&
        ( DAC_BUFFER_MODE_CNT  > xferCtx->Config.BufferMode )    )
    {
        xferConfig->Direction              = GPDMA_DIR_MEMORY_TO_PERIPH;
        xferConfig->XferListExecMode       = dac_DmaListModeLut[ xferCtx->Config.BufferMode ];
        xferConfig->EventMode              = GPDMA_TRANSFER_EVENT_BLOCK;

        xferConfig->TriggerType            = GPDMA_TRG_NOT_USED;
        xferConfig->TriggerMode            = GPDMA_TRIGGER_BLOCK;

        xferConfig->RequestSource          = dac_DmaReqConfig[ periphId ][ channelId ].Request;
        xferConfig->RequestMode            = GPDMA_PERIPH_REQ_SINGLE;

        xferConfig->BlockSize              = (gpdma_BlockSize_t)( (uint32_t)xferCtx->Config.BufferSize * (uint32_t)sizeof( dac_Data_t ) );
        xferConfig->BlockRepetitionCount   = 0u;

        xferConfig->SourceAddr             = (gpdma_SrcAddr_t)(uintptr_t)xferCtx->Config.DataBuffer;
        xferConfig->SourceDataSize         = GPDMA_DATA_SIZE_16BITS;
        xferConfig->SourceBurstLength      = DAC_DMA_BURST_LEN;
        xferConfig->SourceAddrMode         = GPDMA_ADDR_INCREMENT;
        xferConfig->SourcePortId           = GPDMA_PORT_DEFAULT;
        xferConfig->SourceDataOp           = GPDMA_SRC_DATA_PRESERVE;

        xferConfig->DestinationAddr        = (gpdma_DstAddr_t)regAddr;
        xferConfig->DestinationDataSize    = GPDMA_DATA_SIZE_16BITS;
        xferConfig->DestinationBurstLength = DAC_DMA_BURST_LEN;
        xferConfig->DestinationAddrMode    = GPDMA_ADDR_STATIC;
        xferConfig->DestinationPortId      = GPDMA_PORT_DEFAULT;
        xferConfig->DestinationDataOp      = GPDMA_DEST_DATA_PRESERVE;

        retState = DAC_REQUEST_OK;
    }
    else
    {
        retState = DAC_REQUEST_ERROR;
    }

    return ( retState );
}


/**
 * \brief Arms the GPDMA channel for the whole buffer
 *
 * The transfer list node is regenerated from the actual configuration (buffer, buffer mode,
 * data holding register of the data format), the channel link register is loaded from the
 * node (self link in circular mode, terminated list in one shot mode), the first block is
 * written to the channel registers and the channel is enabled.
 *
 * \pre   GPDMA channel is inactive (after initialization, stop or one shot transfer complete).
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
static dac_RequestState_t Dac_Dma_Set_Transfer( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t     retState   = DAC_REQUEST_ERROR;
    gpdma_TransferConfig_t xferConfig = { 0u };

    retState = Dac_Dma_Get_XferConfig( periphId, channelId, &xferConfig );

    if( ( DAC_REQUEST_OK == retState ) && ( DAC_FUNCTION_ACTIVE == dac_DmaChannelState[ periphId ][ channelId ].Initialized ) )
    {
        const gpdma_PeriphId_t           dmaPeriph = (gpdma_PeriphId_t)dac_DmaChannelState[ periphId ][ channelId ].PeriphId;
        const gpdma_ChannelId_t          dmaChan   = (gpdma_ChannelId_t)dac_DmaChannelState[ periphId ][ channelId ].ChannelId;
        const gpdma_ChannelType_t        chanType  = dac_DmaChannelTypeLut[ dac_DmaChannelState[ periphId ][ channelId ].ChannelId ];
        volatile gpdma_XferList_t *const xferNode  = &dac_DmaXferList[ periphId ][ channelId ];
        gpdma_XferLinkReg_t              linkReg   = 0u;
        gpdma_RequestState_t             dmaState  = GPDMA_REQUEST_ERROR;

        /* --- Transfer list node (self linked in circular mode) and channel link register --- */
        dmaState = Gpdma_Get_XferListConfig( &xferConfig, DAC_DMA_TRANSFERS_CNT, chanType, xferNode );

        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Get_XferList_LinkReg( xferNode, chanType, &linkReg );
        }
        else
        {
            /* Transfer list node generation failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_XferListLink( dmaPeriph, dmaChan, linkReg );
        }
        else
        {
            /* Link register is not available */
        }

        /* --- First block in channel registers --- */
        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_BlockSize( dmaPeriph, dmaChan, xferConfig.BlockSize );
        }
        else
        {
            /* Link register configuration failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_SourceAddr( dmaPeriph, dmaChan, xferConfig.SourceAddr );
        }
        else
        {
            /* Block size configuration failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_DestinationAddr( dmaPeriph, dmaChan, xferConfig.DestinationAddr );
        }
        else
        {
            /* Source address configuration failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            dmaState = Gpdma_Set_ChannelActive( dmaPeriph, dmaChan );
        }
        else
        {
            /* Destination address configuration failed */
        }

        if( GPDMA_REQUEST_OK == dmaState )
        {
            retState = DAC_REQUEST_OK;
        }
        else
        {
            retState = DAC_REQUEST_ERROR;
        }
    }
    else
    {
        retState = DAC_REQUEST_ERROR;
    }

    return ( retState );
}


/**
 * \brief Enables / disables DAC DMA requests of a channel (DMAENx) with read-back verification
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 * \param reqState  [in]: DAC_FUNCTION_ACTIVE to enable, DAC_FUNCTION_INACTIVE to disable requests
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
static dac_RequestState_t Dac_Dma_Set_Request( dac_PeriphId_t periphId, dac_ChannelId_t channelId, dac_FunctionState_t reqState )
{
    dac_RequestState_t retState  = DAC_REQUEST_ERROR;
    DAC_TypeDef *      periphReg = DAC_NULL_PTR;
    uint32_t           llChannel = 0u;

    retState = Dac_Get_PeriphReg( periphId, &periphReg );

    if( DAC_REQUEST_OK == retState )
    {
        retState = Dac_Get_LlChannel( channelId, &llChannel );
    }

    if( DAC_REQUEST_OK == retState )
    {
        uint32_t expectedReg = 0u;

        if( DAC_FUNCTION_ACTIVE == reqState )
        {
            LL_DAC_EnableDMAReq( periphReg, llChannel );
            expectedReg = 1u;
        }
        else
        {
            LL_DAC_DisableDMAReq( periphReg, llChannel );
            expectedReg = 0u;
        }

        for( dac_TimeoutCnt_t iterationCnt = 0u; DAC_TIMEOUT_RAW > iterationCnt; iterationCnt ++ )
        {
            const uint32_t dmaReqReg = LL_DAC_IsDMAReqEnabled( periphReg, llChannel );

            if( expectedReg == dmaReqReg )
            {
                retState = DAC_REQUEST_OK;
                break;
            }
            else
            {
                /* DMA request state has not yet been applied, keep return state as error */
                retState = DAC_REQUEST_ERROR;
            }
        }
    }

    return ( retState );
}


/**
 * \brief Transfer complete processing: event is reported to Dac.c (one shot transfer is stopped
 *        there, circular transfer continues - the block is reloaded by GPDMA from the self linked
 *        transfer list node)
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
static dac_RequestState_t Dac_Dma_XferCplt( dac_PeriphId_t periphId, dac_ChannelId_t channelId )
{
    dac_RequestState_t retState = DAC_REQUEST_ERROR;

    retState = Dac_Set_XferDone( periphId, channelId );

    return ( retState );
}


/**
 * \brief DMA error processing: every reported GPDMA error bit is forwarded as DAC error
 *
 * \param periphId  [in]: DAC peripheral identification, value from \ref dac_PeriphId_t
 * \param channelId [in]: DAC channel identification, value from \ref dac_ChannelId_t
 * \param errorMask [in]: GPDMA error bit mask
 *
 * \return Function processing state. Returns \ref DAC_REQUEST_OK if request
 *         was processed without problems. Otherwise returns \ref DAC_REQUEST_ERROR.
 */
static dac_RequestState_t Dac_Dma_XferError( dac_PeriphId_t periphId, dac_ChannelId_t channelId, gpdma_ErrorMaskId_t errorMask )
{
    dac_RequestState_t retState = DAC_REQUEST_OK;

    for( dac_ErrorId_t errorId = DAC_ERROR_DMA_UNDERRUN; DAC_ERROR_CNT > errorId; errorId ++ )
    {
        if( 0u != ( (uint32_t)errorMask & dac_DmaErrorMaskLut[ errorId ] ) )
        {
            retState = Dac_Set_XferError( periphId, channelId, errorId );
        }
        else
        {
            /* Error bit is not reported */
        }
    }

    return ( retState );
}

/* =========================== INTERRUPT HANDLERS =========================== */

/** \brief DAC1 channel 1 DMA transfer complete handler (registered in GPDMA module) */
static void Dac_Dma_Ch1XferCplt( void )
{
    (void)Dac_Dma_XferCplt( DAC_PERIPH_1, DAC_CHANNEL_1 );
}


/** \brief DAC1 channel 1 DMA half transfer handler (registered in GPDMA module) */
static void Dac_Dma_Ch1HalfXfer( void )
{
    (void)Dac_Set_XferHalf( DAC_PERIPH_1, DAC_CHANNEL_1 );
}


/**
 * \brief DAC1 channel 1 DMA error handler (registered in GPDMA module)
 *
 * \param errorMask [in]: Mask of GPDMA errors reported by the channel.
 */
static void Dac_Dma_Ch1Error( gpdma_ErrorMaskId_t errorMask )
{
    (void)Dac_Dma_XferError( DAC_PERIPH_1, DAC_CHANNEL_1, errorMask );
}


/** \brief DAC1 channel 2 DMA transfer complete handler (registered in GPDMA module) */
static void Dac_Dma_Ch2XferCplt( void )
{
    (void)Dac_Dma_XferCplt( DAC_PERIPH_1, DAC_CHANNEL_2 );
}


/** \brief DAC1 channel 2 DMA half transfer handler (registered in GPDMA module) */
static void Dac_Dma_Ch2HalfXfer( void )
{
    (void)Dac_Set_XferHalf( DAC_PERIPH_1, DAC_CHANNEL_2 );
}


/**
 * \brief DAC1 channel 2 DMA error handler (registered in GPDMA module)
 *
 * \param errorMask [in]: Mask of GPDMA errors reported by the channel.
 */
static void Dac_Dma_Ch2Error( gpdma_ErrorMaskId_t errorMask )
{
    (void)Dac_Dma_XferError( DAC_PERIPH_1, DAC_CHANNEL_2, errorMask );
}

